const body = $json.body || $json;
const ALLOWED_SOURCE_TYPES = [
  'INSTALLATION_REPORT', 'SERVICE_REPORT', 'INSPECTION_REPORT', 'FAILURE_REPORT',
  'DRAWING', 'DATASHEET', 'BILL_OF_MATERIAL', 'MAINTENANCE_HISTORY',
  'PUMP_MASTER_EXCEL', 'STOCK_EXCEL', 'INSTALLATION_HISTORY_EXCEL',
  'PHOTO', 'VIDEO', 'ENGINEER_NOTE', 'CUSTOMER_NOTE'
];
const ALLOWED_VERIFICATION_STATUSES = ['DRAFT', 'UNDER_REVIEW', 'VERIFIED', 'CANONICAL'];

if (!body.knowledge_source_id) {
  throw new Error('knowledge_source_id is required');
}

if (body.source_type !== undefined && !ALLOWED_SOURCE_TYPES.includes(body.source_type)) {
  throw new Error('source_type must be one of: ' + ALLOWED_SOURCE_TYPES.join(', '));
}

if (body.verification_status !== undefined && !ALLOWED_VERIFICATION_STATUSES.includes(body.verification_status)) {
  throw new Error('verification_status must be one of: ' + ALLOWED_VERIFICATION_STATUSES.join(', '));
}

if (body.file_size !== undefined && body.file_size !== null && (typeof body.file_size !== 'number' || body.file_size < 0)) {
  throw new Error('file_size must be a non-negative number');
}

// knowledge_source_id is immutable (Business Rule; Architecture Decision) --
// intentionally excluded from the updatable set below.
const updatable = [
  'source_type', 'source_name', 'original_file_name', 'source_date',
  'customer', 'site', 'unit', 'uploaded_by', 'upload_timestamp', 'source_url',
  'verification_status', 'confidence_level', 'file_hash', 'file_size',
  'media_type', 'description'
];

const fields = {};
for (const key of updatable) {
  if (body[key] !== undefined) {
    fields[key] = body[key];
  }
}

if (Object.keys(fields).length === 0) {
  throw new Error('at least one updatable field is required');
}

return [{
  json: {
    knowledge_source_id: body.knowledge_source_id,
    fields
  }
}];

const { knowledge_source_id, fields } = $json;
const keys = Object.keys(fields);

const setClauses = keys.map((key, idx) => `${key} = $${idx + 1}`);
setClauses.push('updated_at = NOW()');

const params = keys.map((key) => fields[key]);
params.push(knowledge_source_id);

const query = `UPDATE knowledge_source_registry SET ${setClauses.join(', ')} WHERE knowledge_source_id = $${params.length} RETURNING *;`;

return [{
  json: {
    knowledge_source_id,
    query,
    params
  }
}];

const row = $input.first()?.json;

if (!row || !row.knowledge_source_id) {
  return [{
    json: {
      statusCode: 404,
      success: false,
      message: 'Knowledge source not found',
      data: null
    }
  }];
}

return [{
  json: {
    statusCode: 200,
    success: true,
    message: 'Knowledge source updated successfully',
    data: row
  }
}];
